export async function getVideoInfo(bvid) {
    try {
        return parseVideoInfoResponse(await fetchWithWBI("/x/web-interface/wbi/view", { bvid }));
    }
    catch (error) {
        if (!(error instanceof NetworkError && error.statusCode === 412)) {
            throw error;
        }
        logger.warn("WBI video info API returned HTTP 412, falling back to /x/web-interface/view", { bvid }, { type: "video-api", operation: "getVideoInfo" });
        return parseVideoInfoResponse(await fetchWithoutWBI("/x/web-interface/view", { bvid }));
    }
}

