function getMixKey(imgKey, subKey) {
    // WBI 签名使用特定的混合顺序
    const saltTable = [
        46, 47, 18, 2, 53, 8, 23, 32, 15, 50, 10, 31, 58, 3, 45, 35, 27, 43, 5,
        49, 33, 9, 42, 19, 29, 28, 14, 39, 12, 38, 41, 13, 37, 48, 7, 16, 24, 55,
        40, 61, 26, 17, 0, 1, 60, 51, 30, 4, 22, 25, 54, 21, 56, 59, 6, 63, 57,
        62, 11, 36, 20, 34, 44, 52,
    ];
    const mixKey = imgKey + subKey;
    return saltTable.map((i) => mixKey[i]).join("");
}

export function generateWBISign(params, mixKey) {
    // 将参数按字典序排序
    const sortedParams = Object.keys(params)
        .sort()
        .reduce((result, key) => {
        result[key] = params[key];
        return result;
    }, {});
    // 构建 query 字符串
    const queryStr = Object.entries(sortedParams)
        .map(([key, value]) => `${key}=${value}`)
        .join("&");
    // 计算 w_rid（使用 MD5 哈希）
    const strToSign = queryStr + mixKey;
    const w_rid = md5Hash(strToSign);
    return w_rid;
}
